-- Women's Basketball History — Seattle Storm 2024 regular-season results v1
-- First 29 results through Aug. 26: official Storm Aug. 28 game notes.
-- Final eleven are exact-or-fail validated against already canonical official-source games, except
-- Sep. 1, Sep. 3 and Sep. 13 which are inserted from official Storm/WNBA game reports.

begin;
do $seed$
declare
  v_run uuid; v_notes_doc uuid; v_doc_sep1 uuid; v_doc_sep3 uuid; v_doc_sep13 uuid; v_now timestamptz:=clock_timestamp();
  v_dataset constant text:='wnba_2024_seattle_storm_results_v1';
  v_notes_url constant text:='https://cdn.wnba.com/sites/1611661330/2024/08/SEA-Game-Notes-2.pdf?page_id=20';
  v_rows constant jsonb:='[{"game_date":"2024-05-14","away":"Minnesota Lynx","away_code":"min","away_points":83,"home":"Seattle Storm","home_code":"sea","home_points":70,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-17","away":"Seattle Storm","away_code":"sea","away_points":93,"home":"Minnesota Lynx","home_code":"min","home_points":102,"overtime_periods":2,"source_kind":"notes"},{"game_date":"2024-05-19","away":"Seattle Storm","away_code":"sea","away_points":84,"home":"Washington Mystics","home_code":"was","home_points":75,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-20","away":"Seattle Storm","away_code":"sea","away_points":63,"home":"New York Liberty","home_code":"nyl","home_points":74,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-22","away":"Indiana Fever","away_code":"ind","away_points":83,"home":"Seattle Storm","home_code":"sea","home_points":85,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-25","away":"Washington Mystics","away_code":"was","away_points":69,"home":"Seattle Storm","home_code":"sea","home_points":101,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-28","away":"Seattle Storm","away_code":"sea","away_points":77,"home":"Chicago Sky","home_code":"chi","home_points":68,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-05-30","away":"Seattle Storm","away_code":"sea","away_points":103,"home":"Indiana Fever","home_code":"ind","home_points":88,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-04","away":"Phoenix Mercury","away_code":"phx","away_points":62,"home":"Seattle Storm","home_code":"sea","home_points":80,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-07","away":"Seattle Storm","away_code":"sea","away_points":78,"home":"Las Vegas Aces","home_code":"lva","home_points":65,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-09","away":"Seattle Storm","away_code":"sea","away_points":64,"home":"Minnesota Lynx","home_code":"min","home_points":83,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-11","away":"Los Angeles Sparks","away_code":"las","away_points":79,"home":"Seattle Storm","home_code":"sea","home_points":95,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-13","away":"Seattle Storm","away_code":"sea","away_points":92,"home":"Dallas Wings","home_code":"dal","home_points":84,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-16","away":"Seattle Storm","away_code":"sea","away_points":78,"home":"Phoenix Mercury","home_code":"phx","home_points":87,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-19","away":"Seattle Storm","away_code":"sea","away_points":83,"home":"Las Vegas Aces","home_code":"lva","home_points":94,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-23","away":"Connecticut Sun","away_code":"con","away_points":61,"home":"Seattle Storm","home_code":"sea","home_points":72,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-27","away":"Indiana Fever","away_code":"ind","away_points":77,"home":"Seattle Storm","home_code":"sea","home_points":89,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-06-29","away":"Dallas Wings","away_code":"dal","away_points":76,"home":"Seattle Storm","home_code":"sea","home_points":97,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-01","away":"Dallas Wings","away_code":"dal","away_points":71,"home":"Seattle Storm","home_code":"sea","home_points":95,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-05","away":"Chicago Sky","away_code":"chi","away_points":88,"home":"Seattle Storm","home_code":"sea","home_points":84,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-07","away":"Chicago Sky","away_code":"chi","away_points":71,"home":"Seattle Storm","home_code":"sea","home_points":84,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-10","away":"Las Vegas Aces","away_code":"lva","away_points":84,"home":"Seattle Storm","home_code":"sea","home_points":79,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-12","away":"Minnesota Lynx","away_code":"min","away_points":63,"home":"Seattle Storm","home_code":"sea","home_points":91,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-14","away":"Atlanta Dream","away_code":"atl","away_points":70,"home":"Seattle Storm","home_code":"sea","home_points":81,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-07-16","away":"Seattle Storm","away_code":"sea","away_points":89,"home":"Los Angeles Sparks","home_code":"las","home_points":83,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-08-16","away":"Seattle Storm","away_code":"sea","away_points":81,"home":"Atlanta Dream","home_code":"atl","home_points":83,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-08-18","away":"Seattle Storm","away_code":"sea","away_points":75,"home":"Indiana Fever","home_code":"ind","home_points":92,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-08-20","away":"Seattle Storm","away_code":"sea","away_points":83,"home":"Washington Mystics","home_code":"was","home_points":77,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-08-26","away":"Washington Mystics","away_code":"was","away_points":74,"home":"Seattle Storm","home_code":"sea","home_points":72,"overtime_periods":0,"source_kind":"notes"},{"game_date":"2024-08-28","away":"Atlanta Dream","away_code":"atl","away_points":81,"home":"Seattle Storm","home_code":"sea","home_points":85,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-08-30","away":"New York Liberty","away_code":"nyl","away_points":98,"home":"Seattle Storm","home_code":"sea","home_points":85,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-01","away":"Seattle Storm","away_code":"sea","away_points":86,"home":"Connecticut Sun","home_code":"con","home_points":93,"overtime_periods":0,"source_kind":"storm_sep1"},{"game_date":"2024-09-03","away":"Seattle Storm","away_code":"sea","away_points":71,"home":"Connecticut Sun","home_code":"con","home_points":64,"overtime_periods":0,"source_kind":"storm_sep3"},{"game_date":"2024-09-05","away":"Seattle Storm","away_code":"sea","away_points":70,"home":"New York Liberty","home_code":"nyl","home_points":77,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-07","away":"Phoenix Mercury","away_code":"phx","away_points":66,"home":"Seattle Storm","home_code":"sea","home_points":90,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-11","away":"Seattle Storm","away_code":"sea","away_points":90,"home":"Los Angeles Sparks","home_code":"las","home_points":82,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-13","away":"Seattle Storm","away_code":"sea","away_points":83,"home":"Dallas Wings","home_code":"dal","home_points":81,"overtime_periods":0,"source_kind":"wnba_sep13"},{"game_date":"2024-09-15","away":"Los Angeles Sparks","away_code":"las","away_points":87,"home":"Seattle Storm","home_code":"sea","home_points":90,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-17","away":"Las Vegas Aces","away_code":"lva","away_points":85,"home":"Seattle Storm","home_code":"sea","home_points":72,"overtime_periods":0,"source_kind":"validate"},{"game_date":"2024-09-19","away":"Seattle Storm","away_code":"sea","away_points":89,"home":"Phoenix Mercury","home_code":"phx","home_points":70,"overtime_periods":0,"source_kind":"validate"}]'::jsonb;
  r record; v_game_id text; v_inserted integer:=0; v_validated integer:=0; v_match integer; v_capture text; v_existing integer; v_total integer; v_doc uuid;
begin
  perform public.wbh_assert_ingestible('pbe_curation');
  select count(*) into v_existing from public.wbh_ingestion_runs where scope->>'dataset'=v_dataset and status='ok'; if v_existing>0 then return; end if;
  select jsonb_agg(e.value order by e.ord)::text into v_capture from jsonb_array_elements(v_rows) with ordinality e(value,ord) where e.value->>'source_kind'='notes';
  insert into public.wbh_source_documents(source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values('pbe_curation','seattle_storm_2024_results_through_20240826',v_notes_url,'GET',v_now,200,encode(extensions.digest(convert_to(v_capture,'UTF8'),'sha256'),'hex'),'application/json',octet_length(v_capture),'hash_only','wbh_manual_game_results_v1','Manual factual transcription from official Seattle Storm Aug. 28 game notes schedule/results table through Aug. 26; source PDF body not retained.') returning document_id into v_notes_doc;
  insert into public.wbh_source_documents(source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes) values
  ('pbe_curation','storm_2024_09_01_result','https://storm.wnba.com/news/storm-rallies-late-but-falls-to-sun-93-86','GET',v_now,200,encode(extensions.digest(convert_to('2024-09-01|SEA|86|CON|93','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Manual factual transcription from official Seattle Storm game recap; page body not retained.') returning document_id into v_doc_sep1;
  insert into public.wbh_source_documents(source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes) values
  ('pbe_curation','storm_2024_09_03_result','https://storm.wnba.com/news/storm-eclipses-sun-71-64-to-earn-key-road-win','GET',v_now,200,encode(extensions.digest(convert_to('2024-09-03|SEA|71|CON|64','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Manual factual transcription from official Seattle Storm game recap; page body not retained.') returning document_id into v_doc_sep3;
  insert into public.wbh_source_documents(source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes) values
  ('pbe_curation','wnba_game_1022400221','https://www.wnba.com/game/sea-vs-dal-1022400221','GET',v_now,200,encode(extensions.digest(convert_to('2024-09-13|SEA|83|DAL|81','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Manual factual transcription from official WNBA.com game summary; page body not retained.') returning document_id into v_doc_sep13;
  insert into public.wbh_ingestion_runs(source_id,adapter_id,adapter_version,transformation_version,mode,as_of,scope)
  values('pbe_curation','manual_public_game_curation','1.0.0','wbh_manual_game_results_v1','ingest',v_now,jsonb_build_object('dataset',v_dataset,'edition_id','wnba_2024','input_rows',40,'regular_games',40,'notes_rows',29,'direct_result_rows',3,'cross_source_validation_rows',8,'dedupe_policy','exact_or_fail','roster_stints_written',0,'player_game_stats_written',0)) returning run_id into v_run;
  for r in select * from jsonb_to_recordset(v_rows) as x(game_date date,away text,away_code text,away_points integer,home text,home_code text,home_points integer,overtime_periods integer,source_kind text) order by game_date loop
    v_game_id:='gm_wnba_2024_'||to_char(r.game_date,'YYYYMMDD')||'_'||r.away_code||'_at_'||r.home_code;
    v_doc:=case r.source_kind when 'notes' then v_notes_doc when 'storm_sep1' then v_doc_sep1 when 'storm_sep3' then v_doc_sep3 when 'wnba_sep13' then v_doc_sep13 else null end;
    if exists(select 1 from public.wbh_games where game_id=v_game_id) then
      select count(*) into v_match from public.wbh_games g where g.game_id=v_game_id and g.edition_id='wnba_2024' and g.local_date=r.game_date and g.stage_id='wnba_2024_regular_season' and g.game_type='regular' and g.season_phase='regular_season' and g.counts_for_standings and g.counts_for_stats and g.status='final' and g.completeness='score_only' and g.overtime_periods=r.overtime_periods
      and exists(select 1 from public.wbh_game_teams gt join public.wbh_team_editions te on te.team_edition_id=gt.team_edition_id where gt.game_id=g.game_id and gt.side='away' and te.display_name=r.away and gt.points=r.away_points)
      and exists(select 1 from public.wbh_game_teams gt join public.wbh_team_editions te on te.team_edition_id=gt.team_edition_id where gt.game_id=g.game_id and gt.side='home' and te.display_name=r.home and gt.points=r.home_points);
      if v_match<>1 then raise exception 'wbh: Storm source disagrees with existing game %',v_game_id using errcode='P0001'; end if; v_validated:=v_validated+1;
    else
      if v_doc is null then raise exception 'wbh: new Storm game % has no direct source document',v_game_id using errcode='P0001'; end if;
      insert into public.wbh_games(game_id,edition_id,stage_id,competition_id,local_date,status,game_type,season_phase,counts_for_standings,counts_for_stats,overtime_periods,completeness,source_document_id,ingestion_run_id,transformation_version,derivation)
      values(v_game_id,'wnba_2024','wnba_2024_regular_season','wnba',r.game_date,'final','regular','regular_season',true,true,r.overtime_periods,'score_only',v_doc,v_run,'wbh_manual_game_results_v1','manual_curation:official_storm_schedule_results');
      insert into public.wbh_game_teams(game_id,team_edition_id,side,points,result,source_document_id,ingestion_run_id,transformation_version,derivation)
      select v_game_id,te.team_edition_id,'away',r.away_points,case when r.away_points>r.home_points then 'win' else 'loss' end,v_doc,v_run,'wbh_manual_game_results_v1','manual_curation:official_storm_schedule_results' from public.wbh_team_editions te where te.edition_id='wnba_2024' and te.display_name=r.away
      union all select v_game_id,te.team_edition_id,'home',r.home_points,case when r.home_points>r.away_points then 'win' else 'loss' end,v_doc,v_run,'wbh_manual_game_results_v1','manual_curation:official_storm_schedule_results' from public.wbh_team_editions te where te.edition_id='wnba_2024' and te.display_name=r.home;
      v_inserted:=v_inserted+1;
    end if;
  end loop;
  select count(distinct gt.game_id) into v_total from public.wbh_game_teams gt join public.wbh_games g using(game_id) where g.edition_id='wnba_2024' and gt.team_edition_id='te_seattle_storm_2024' and g.game_type='regular';
  if v_total<>40 then raise exception 'wbh: Storm final regular-game count % not 40',v_total using errcode='P0001'; end if;
  update public.wbh_ingestion_runs set status='ok',counts=jsonb_build_object('input_rows',40,'inserted_games',v_inserted,'validated_existing_games',v_validated,'regular_games',40,'canonical_storm_games',v_total,'roster_stints_written',0,'player_game_stats_written',0) where run_id=v_run;
end $seed$;
commit;
